import{_ as a,o as i,c as e,aO as n}from"./chunks/framework.vjUPZZJn.js";const o=JSON.parse('{"title":"Linux 使用 Clash 代理客户端：安装、systemd 常驻与终端代理","description":"","frontmatter":{"date":"2026-10-14T03:20:00.000Z","title":"Linux 使用 Clash 代理客户端：安装、systemd 常驻与终端代理","source":[["1-知识/工具/网络代理与远程/ClashForLinux"]],"tags":["工具","教程手册","网络代理","Linux"],"categories":["工具"],"permalink":"/pages/43563e"},"headers":[],"relativePath":"工具/Linux 使用 Clash 代理客户端：安装、systemd 常驻与终端代理.md","filePath":"工具/Linux 使用 Clash 代理客户端：安装、systemd 常驻与终端代理.md","lastUpdated":1792031351000}'),l={name:"工具/Linux 使用 Clash 代理客户端：安装、systemd 常驻与终端代理.md"};function t(p,s,h,r,d,k){return i(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="linux-使用-clash-代理客户端-安装、systemd-常驻与终端代理" tabindex="-1">Linux 使用 Clash 代理客户端：安装、systemd 常驻与终端代理 <a class="header-anchor" href="#linux-使用-clash-代理客户端-安装、systemd-常驻与终端代理" aria-label="Permalink to &quot;Linux 使用 Clash 代理客户端：安装、systemd 常驻与终端代理&quot;">​</a></h1> <p>在无桌面环境的 Linux 服务器上，如果网络访问需要统一经过代理网关（例如隔离网络中只有代理机能出站），Clash 是一个常用选择：单个静态二进制、配置文件驱动、自带规则分流。本文记录从下载、配置到 systemd 服务化的完整步骤，以及让终端命令（curl、git、包管理器）走代理的环境变量写法。</p> <h2 id="仓库现状" tabindex="-1">仓库现状 <a class="header-anchor" href="#仓库现状" aria-label="Permalink to &quot;仓库现状&quot;">​</a></h2> <p>原版 Clash 仓库（Dreamacro/clash）已于 2023 年 11 月归档停止维护，目前社区活跃的接续分支是 <a href="https://github.com/MetaCubeX/mihomo" target="_blank" rel="noreferrer">MetaCubeX/mihomo</a>（即 Clash.Meta），配置格式与使用方式基本兼容。下文步骤以原版 Clash 的用法为基准，对 mihomo 同样适用，新环境建议直接安装 mihomo。</p> <h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2> <p>从 release 页面下载对应架构的二进制（Ubuntu x86_64 为 <code>clash-linux-amd64</code>，mihomo 的命名类似）：</p> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gunzip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clash-linux-amd64-v1.xx.0.gz</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clash-linux-amd64-v1.xx.0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clash</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> u+x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clash</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>首次启动时 Clash 会自动下载 <code>Country.mmdb</code>（GeoIP 数据库，用于按地理位置分流）到 <code>~/.config/clash</code>。网络较慢时可从 <a href="https://github.com/Dreamacro/maxmind-geoip/releases" target="_blank" rel="noreferrer">maxmind-geoip release</a> 手动下载后放到同一位置。</p> <h2 id="配置文件" tabindex="-1">配置文件 <a class="header-anchor" href="#配置文件" aria-label="Permalink to &quot;配置文件&quot;">​</a></h2> <p>Clash 的全部行为由一个 YAML 配置决定。网络管理员提供订阅链接时，直接下载为 <code>config.yaml</code>：</p> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config.yaml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;https://订阅链接&#39;</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>短链接服务有重定向，需加 <code>-L</code>：</p> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config.yaml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;https://短链接&#39;</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>配置的核心字段：<code>port</code>/<code>mixed-port</code> 是本地代理监听端口（默认 HTTP 7890、SOCKS 7891，<code>mixed-port</code> 则单端口双协议）；<code>proxies</code> 定义上游代理；<code>rules</code> 决定哪些目标走代理、哪些直连。</p> <h2 id="systemd-服务化" tabindex="-1">systemd 服务化 <a class="header-anchor" href="#systemd-服务化" aria-label="Permalink to &quot;systemd 服务化&quot;">​</a></h2> <p>登录会话退出后前台进程会被挂断，用 systemd 把 Clash 注册为系统服务实现常驻与开机自启。把可执行文件与配置归位：</p> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mkdir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/clash</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/local/bin</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config.yaml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Country.mmdb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/clash/</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>创建 <code>/etc/systemd/system/clash.service</code>：</p> <div class="language-ini vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[Unit]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=Clash daemon, A rule-based proxy in Go.</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">After</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=network.target</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[Service]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=simple</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Restart</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=always</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ExecStart</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=/usr/local/bin/clash -d /etc/clash</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[Install]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WantedBy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=multi-user.target</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p><code>-d</code> 指定配置目录，<code>Restart=always</code> 保证进程异常退出后自动拉起。启用并启动：</p> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clash</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clash</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>查看运行状态与日志：</p> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clash</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h2 id="让终端命令走代理" tabindex="-1">让终端命令走代理 <a class="header-anchor" href="#让终端命令走代理" aria-label="Permalink to &quot;让终端命令走代理&quot;">​</a></h2> <p>Clash 起来之后只是一个本地端口，命令行工具不认系统代理设置，需要环境变量：</p> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> http_proxy</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://127.0.0.1:7890</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> https_proxy</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://127.0.0.1:7890</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> all_proxy</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">socks5://127.0.0.1:7891</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>验证：</p> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://www.google.com</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;&amp;1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> connected</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>想登录后自动生效，把上面三行写进 <code>~/.bashrc</code>。临时关闭代理：</p> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">unset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http_proxy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https_proxy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> all_proxy</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>git 若需单独配置：<code>git config --global http.proxy http://127.0.0.1:7890</code>（仅对 HTTP(S) 协议的远端生效，SSH 协议需另行配置 ProxyCommand）。</p> <h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2> <p>单个二进制加一份 YAML，Clash（或其接续分支 mihomo）在服务器上的部署成本很低：下载二进制、放好 config.yaml 与 GeoIP 库、写一个十行的 systemd unit，即可获得带规则分流与自动重启的常驻代理；终端侧配好三个环境变量即可让绝大多数命令行工具走代理。</p> <h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考&quot;">​</a></h2> <ul><li><a href="https://blog.iswiftai.com/posts/clash-linux/" target="_blank" rel="noreferrer">在 Linux 中使用 Clash</a></li> <li><a href="https://github.com/MetaCubeX/mihomo" target="_blank" rel="noreferrer">MetaCubeX/mihomo</a>（原版 Clash 的活跃接续分支）</li></ul>`,59)])])}const u=a(l,[["render",t]]);export{o as __pageData,u as default};
